bench ! (hn_hdrs_set_11_get_with_miss (new_map , b) { let hdrs : Vec < (HeaderName , &'static str) > = super :: HN_HDRS . iter () . map (|& (name , val) | (name . parse () . unwrap () , val)) . collect () ; let miss : HeaderName = "x-wat" . parse () . unwrap () ; b . iter (|| { let mut h = new_map () ; for & (ref name , val) in hdrs . iter () { h . insert (name . clone () , val) ; } for _ in 0 .. 10 { test :: black_box (h . get (& CONTENT_LENGTH)) ; test :: black_box (h . get (& VARY)) ; test :: black_box (h . get (& miss)) ; } }) ; }) ;